/**
 * Bindings drift guard.
 *
 * Why: `src/bindings.ts` is generated by tauri-specta, but only from a *debug*
 * build at app startup (see the `#[cfg(debug_assertions)]` export in
 * `src-tauri/src/lib.rs`). Nothing regenerates it in CI. So adding a Tauri
 * command and forgetting to run `bun run tauri dev` once leaves the frontend
 * calling a binding that does not exist — and the release build happily
 * regenerates the file first, hiding the drift from the only job that would
 * have caught it.
 *
 * What this checks: every command registered in the `collect_commands![...]`
 * block in lib.rs has a matching `TAURI_INVOKE("<name>", ...)` in bindings.ts,
 * and vice versa. Same for the `collect_events![...]` payload types.
 *
 * What this does NOT check: parameter and return *types*. Verifying those would
 * mean regenerating the bindings, which needs a full debug build of the Rust
 * crate. This guard catches the failure mode that actually happens (a command
 * added, renamed or removed without regenerating) at the cost of a file read.
 *
 * Exit codes: 0 clean, 1 drift found, 2 infrastructure error.
 */

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, "..", "..");
const LIB_RS = path.join(ROOT, "src-tauri", "src", "lib.rs");
const BINDINGS = path.join(ROOT, "src", "bindings.ts");

const colors = {
  red: "\x1b[31m",
  green: "\x1b[32m",
  yellow: "\x1b[33m",
  reset: "\x1b[0m",
};

function colorize(text: string, color: keyof typeof colors): string {
  return `${colors[color]}${text}${colors.reset}`;
}

function fail(message: string): never {
  console.error(colorize(`✗ ${message}`, "red"));
  process.exit(2);
}

function read(file: string, label: string): string {
  try {
    return fs.readFileSync(file, "utf8");
  } catch (error) {
    fail(`cannot read ${label} at ${file}: ${(error as Error).message}`);
  }
}

/** Extract the contents of a `macroName![ ... ]` block, brackets excluded. */
function macroBlock(source: string, macroName: string): string {
  const marker = `${macroName}![`;
  const start = source.indexOf(marker);
  if (start === -1) {
    fail(`no ${marker} block found in lib.rs — has the specta setup moved?`);
  }

  let depth = 0;
  for (let i = start + marker.length - 1; i < source.length; i++) {
    const char = source[i];
    if (char === "[") depth++;
    else if (char === "]") {
      depth--;
      if (depth === 0) {
        return source.slice(start + marker.length, i);
      }
    }
  }
  fail(`unterminated ${marker} block in lib.rs`);
}

/** Last path segment of each `a::b::c,` entry in a macro block. */
function lastSegments(block: string): string[] {
  return block
    .split("\n")
    .map((line) => line.replace(/\/\/.*$/, "").trim())
    .filter((line) => line.length > 0)
    .map((line) => line.replace(/,$/, "").trim())
    .filter((line) => /^[A-Za-z_][A-Za-z0-9_:]*$/.test(line))
    .map((entry) => entry.split("::").pop() as string);
}

function difference(a: Set<string>, b: Set<string>): string[] {
  return [...a].filter((value) => !b.has(value)).sort();
}

function report(
  label: string,
  onlyInRust: string[],
  onlyInBindings: string[],
): boolean {
  if (onlyInRust.length === 0 && onlyInBindings.length === 0) {
    console.log(colorize(`✓ ${label}: in sync`, "green"));
    return true;
  }

  console.error(colorize(`✗ ${label}: out of sync`, "red"));
  for (const name of onlyInRust) {
    console.error(
      `    registered in lib.rs but missing from bindings.ts: ${name}`,
    );
  }
  for (const name of onlyInBindings) {
    console.error(
      `    present in bindings.ts but not registered in lib.rs: ${name}`,
    );
  }
  return false;
}

function main(): void {
  const libSource = read(LIB_RS, "lib.rs");
  const bindingsSource = read(BINDINGS, "src/bindings.ts");

  // --- commands -----------------------------------------------------------
  const rustCommands = new Set(
    lastSegments(macroBlock(libSource, "collect_commands")),
  );
  if (rustCommands.size === 0) {
    fail("parsed zero commands out of collect_commands! — the guard is broken");
  }

  const bindingCommands = new Set<string>();
  for (const match of bindingsSource.matchAll(
    /TAURI_INVOKE\("([a-z0-9_]+)"/g,
  )) {
    bindingCommands.add(match[1]);
  }
  if (bindingCommands.size === 0) {
    fail(
      "parsed zero TAURI_INVOKE names out of bindings.ts — the guard is broken",
    );
  }

  const commandsOk = report(
    `commands (${rustCommands.size} registered)`,
    difference(rustCommands, bindingCommands),
    difference(bindingCommands, rustCommands),
  );

  // --- events -------------------------------------------------------------
  // Event payload types are registered by Rust type name and surface in
  // bindings.ts as `__EVENTS__` keys in snake_case.
  const rustEvents = lastSegments(macroBlock(libSource, "collect_events"));
  const snake = (name: string) =>
    name
      .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
      .replace(/([A-Z]+)([A-Z][a-z])/g, "$1_$2")
      .toLowerCase();

  const missingEvents = rustEvents.filter(
    (name) =>
      !bindingsSource.includes(`"${snake(name)}"`) &&
      !bindingsSource.includes(name),
  );

  const eventsOk =
    missingEvents.length === 0
      ? (console.log(
          colorize(
            `✓ events (${rustEvents.length} registered): in sync`,
            "green",
          ),
        ),
        true)
      : (console.error(colorize("✗ events: out of sync", "red")),
        missingEvents.forEach((name) =>
          console.error(
            `    registered in lib.rs but missing from bindings.ts: ${name}`,
          ),
        ),
        false);

  if (commandsOk && eventsOk) {
    console.log(
      colorize(
        "\n✓ src/bindings.ts is in sync with the Rust command surface",
        "green",
      ),
    );
    process.exit(0);
  }

  console.error(
    colorize(
      "\nRegenerate the bindings by starting the app once in debug mode:\n" +
        "    bun run tauri dev\n" +
        "then commit the updated src/bindings.ts.",
      "yellow",
    ),
  );
  process.exit(1);
}

main();
